"""Fresh interactive capture -> native Miles per-turn Samples, without training.

This adapter invokes Miles' real session-record assembler. It never tokenizes an
assistant's historical text, invents missing log probabilities, merges changed
contexts, invents a reward, or runs an optimizer. Capture hashes establish byte
integrity; the owner still has to authenticate the collector and serving model.
"""

from __future__ import annotations

import hashlib
import json
import math
import sys
from argparse import Namespace
from copy import deepcopy
from pathlib import Path
from typing import Any

SCHEMA = "ndfeb-miles-investigation-v1"
MILES_COMMIT = "ab48452eaf35ef6beaf9c745e1c923bf261bd235"
MILES_SOURCE_HASHES = {
    "miles.rollout.session.samples.merge": "1bf56eac98f6a76ea536f3f1b4934272c94ae4b39ce4fce9b9e9fd8ec608e636",
    "miles.rollout.session.types": "a724c517f6b2bfbfa56639e0ff88ab2b50d22564201fe4dde7701aac7317e2ef",
    "miles.utils.types": "eb367e28cecc55adbafebe7bed8ea96800cf63f7cac0b3caf90798480495b85a",
}
MILES_GROUP_SOURCE_HASHES = {
    "miles.ray.rollout.train_data_conversion": "1b4d470b9697f702890f28c8b5956609c84d1215538706cc3dcb9061ffafc8a7",
    "miles.ray.rollout.rollout_data_conversion": "b776cab6b0b61aa145ad895128269697a8f9b0cc39117eec61a160e250e7b6af",
}


class InvestigationCaptureError(ValueError):
    """A record lacks the native evidence needed for this no-update interface."""


def capture_sha256(value: Any) -> str:
    return hashlib.sha256(
        json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False).encode()
    ).hexdigest()


def _require(condition, message):
    if not condition:
        raise InvestigationCaptureError(message)


def _hash(value):
    return isinstance(value, str) and len(value) == 64 and all(
        c in "0123456789abcdef" for c in value
    )


def _number(value):
    return not isinstance(value, bool) and isinstance(value, (int, float)) and math.isfinite(value)


def _token_ids(value):
    return isinstance(value, list) and bool(value) and all(
        isinstance(token, int) and not isinstance(token, bool) and token >= 0 for token in value
    )


def validate_policy_identity(policy, expected_policy):
    """Match a separately frozen serving identity; names alone are insufficient."""
    _require(isinstance(policy, dict) and policy == expected_policy, "Serving policy identity changed")
    _require(policy.get("model_name") == "GLM-5.3-Flash", "Exact GLM-5.3-Flash required")
    _require(policy.get("model_type") == "glm5_next", "Exact glm5_next architecture required")
    _require(policy.get("num_hidden_layers") == 45, "Full 45-layer model required, not a slice")
    for key in ("checkpoint_revision", "weight_version", "precision"):
        _require(isinstance(policy.get(key), str) and policy[key].strip()
                 and policy[key].strip().lower() not in {"unknown", "unverified", "none", "default"},
                 f"Missing exact policy field: {key}")
    for key in ("tokenizer_sha256", "chat_template_sha256"):
        _require(_hash(policy.get(key)), f"Missing source hash: {key}")
    _require(policy.get("tito_model") == "glm53", "Miles GLM53 text tokenizer contract required")
    kwargs = policy.get("chat_template_kwargs", {})
    _require(kwargs.get("clear_thinking") is False and kwargs.get("enable_thinking") is True,
             "GLM53 requires clear_thinking=False and enable_thinking=True")


def _version_spans(meta, count, expected):
    if "weight_versions" in meta:
        spans = meta["weight_versions"]
        _require(isinstance(spans, list) and bool(spans), "Empty returned weight-version spans")
    else:
        _require(isinstance(meta.get("weight_version"), str), "Native response lacks weight version")
        spans = [{"version": meta["weight_version"], "start": 0, "end": count}]
    cursor = 0
    for span in spans:
        _require(isinstance(span, dict), "Invalid returned weight-version span")
        start, end = span.get("start"), span.get("end")
        _require(type(start) is int and type(end) is int and start == cursor < end <= count,
                 "Returned weight-version spans must cover each output token once")
        _require(span.get("version") == expected, "Policy version changed within no-update investigation")
        cursor = end
    _require(cursor == count, "Returned weight-version spans leave output tokens unbound")
    if "weight_version" in meta:
        _require(meta["weight_version"] == expected, "Conflicting native weight-version metadata")


def validate_investigation_capture(bundle, *, expected_policy, allow_test_fixtures=False):
    """Validate fresh native inputs and custody without inferring authenticity.

    Test fixtures require an explicit opt-in and remain labeled in every Sample.
    Standard historical experience/prompt records are deliberately not accepted.
    """
    _require(isinstance(bundle, dict) and bundle.get("schema") == SCHEMA,
             "Expected fresh interactive capture, not a historical experience record")
    origin = bundle.get("origin")
    _require(origin == "fresh_interactive" or
             (allow_test_fixtures and origin == "explicit_test_fixture"),
             "Only fresh native capture is admitted; fixtures need explicit diagnostic opt-in")
    validate_policy_identity(bundle.get("policy_identity"), expected_policy)
    for key in ("rollout_id", "group_index"):
        _require(type(bundle.get(key)) is int and bundle[key] >= 0, f"Invalid {key}")
    _require(isinstance(bundle.get("episode_id"), str) and bundle["episode_id"], "Missing episode identity")
    turns = bundle.get("turns")
    _require(isinstance(turns, list) and bool(turns), "No native generation records")
    terminal = bundle.get("terminal", {})
    _require(terminal.get("reason") == "scientific_stop" and _hash(terminal.get("receipt_sha256")),
             "Scientific completion requires a bound stop receipt; waiting/failure is not completion")
    previous = None
    seen = set()
    diagnostics = []
    for index, turn in enumerate(turns):
        call_id = turn.get("call_id")
        _require(isinstance(call_id, str) and call_id and call_id not in seen, "Missing/duplicate native call identity")
        seen.add(call_id)
        _require(turn.get("parent_call_id") == (previous["call_id"] if previous else None),
                 "Native call ancestry is incomplete or reordered")
        transition = turn.get("context_transition")
        _require(transition == "initial" if index == 0 else transition in {"append", "compaction", "resume"},
                 "Invalid context transition")
        if transition in {"compaction", "resume"}:
            _require(_hash(turn.get("context_event_sha256")), "Context reset/resume lacks native event binding")
        record = turn.get("record", {})
        request, response = record.get("request", {}), record.get("response", {})
        _require(record.get("method") == "POST" and record.get("status_code") == 200,
                 "Native call was not a successful POST")
        _require(record.get("path") in {"/v1/chat/completions", "/chat/completions"},
                 "Expected native SGLang chat-completion record")
        start, end = record.get("request_timestamp"), record.get("timestamp")
        _require(_number(start) and _number(end) and start <= end, "Invalid native call chronology")
        if previous:
            _require(start >= previous["record"]["timestamp"], "Native generation chronology overlaps")
        _require(turn.get("request_sha256") == capture_sha256(request), "Enriched native request hash mismatch")
        _require(turn.get("response_sha256") == capture_sha256(response), "Native response hash mismatch")
        _require(_hash(turn.get("wire_request_sha256")), "Exact original wire request hash missing")
        _require(turn.get("input_ids_origin") == "server_returned_prompt_token_ids",
                 "Prompt tokens must come from the actual serving request, not later retokenization")
        _require(_token_ids(request.get("input_ids")), "Missing exact native prompt token IDs")
        _require(isinstance(request.get("messages"), list), "Native request lacks tool/message history")
        _require(request.get("chat_template_kwargs") == expected_policy["chat_template_kwargs"],
                 "Request changed the frozen GLM53 template behavior")
        choices = response.get("choices")
        _require(isinstance(choices, list) and len(choices) == 1, "Exactly one native policy continuation required")
        choice = choices[0]
        meta = choice.get("meta_info", {})
        logs = meta.get("output_token_logprobs")
        _require(isinstance(logs, list) and bool(logs), "Missing native sampled token log probabilities")
        for item in logs:
            _require(isinstance(item, (list, tuple)) and len(item) >= 2
                     and _number(item[0]) and item[0] <= 1e-6
                     and type(item[1]) is int and item[1] >= 0,
                     "Malformed native token/log-probability pair")
        output_ids = [item[1] for item in logs]
        _require(type(meta.get("completion_tokens")) is int
                 and meta["completion_tokens"] == len(output_ids),
                 "Incomplete generated token/logprob alignment")
        _require(choice.get("prompt_token_ids") == request["input_ids"], "Server prompt tokens differ from native record")
        _require(choice.get("response_token_ids") == output_ids, "Server output tokens differ from log-probability tokens")
        _version_spans(meta, len(output_ids), expected_policy["weight_version"])
        _require(not meta.get("routed_experts") and not meta.get("indexer_topk"),
                 "This text-only adapter does not admit unverified routing/indexer replay payloads")
        finish = choice.get("finish_reason")
        _require(finish in {"stop", "tool_calls", "length"}, "Native generation failed or was aborted")
        if index == len(turns) - 1:
            _require(finish != "length", "Last generation is censored, not scientifically complete")
        message = choice.get("message", {})
        _require(message.get("role") == "assistant", "Native response lacks assistant message")
        calls = message.get("tool_calls") or []
        call_ids = [call.get("id") for call in calls]
        _require(all(isinstance(x, str) and x for x in call_ids) and len(set(call_ids)) == len(call_ids),
                 "Invalid native tool-call identities")
        observations = turn.get("tool_observations", [])
        _require(isinstance(observations, list), "Tool observations must retain their native records")
        _require(sorted(o.get("tool_call_id", "") for o in observations) == sorted(call_ids),
                 "Each dispatched tool call requires exactly one retained observation")
        for observation in observations:
            observed = observation.get("message", {})
            _require(observed.get("role") == "tool"
                     and observed.get("tool_call_id") == observation["tool_call_id"]
                     and isinstance(observed.get("content"), str)
                     and _hash(observation.get("receipt_sha256")), "Malformed or unbound native tool observation")
            completed = observation.get("completed_at")
            _require(_number(completed) and completed >= end, "Tool observation predates policy generation")
            if index + 1 < len(turns):
                nxt = turns[index + 1]
                _require(completed <= nxt["record"]["request_timestamp"], "Tool result arrived after the next decision")
                if nxt["context_transition"] == "append":
                    _require(observed in nxt["record"]["request"]["messages"], "Next appended prompt omitted or changed tool observation")
        if previous:
            old = previous["record"]
            old_ids = old["request"]["input_ids"] + old["response"]["choices"][0]["response_token_ids"]
            new_ids = request["input_ids"]
            exact_prefix = new_ids[:len(old_ids)] == old_ids
            diagnostics.append({"call_id": call_id, "context_transition": transition,
                                "prior_sample_tokens_are_exact_prefix": exact_prefix,
                                "samples_merged": False})
        previous = turn
    _require(terminal.get("last_call_id") == turns[-1]["call_id"], "Terminal receipt does not bind final native call")
    return {"origin": origin, "calls": len(turns), "context_diagnostics": diagnostics,
            "capture_sha256": capture_sha256(bundle),
            "authenticity": "Requires owner verification of retained collector and serving receipts; hashes alone prove integrity."}


def build_miles_investigation(bundle, tokenizer, *, expected_policy, allow_test_fixtures=False):
    """Invoke upstream native session assembly and preserve complete trial linkage.

    Every turn has its actual full prompt and only its newly generated response
    contributes loss. Thus tool observations and prior assistant outputs are
    context, never fabricated output tokens or duplicated optimization targets.
    Per-turn Samples share a rollout_id; this also preserves compaction without
    pretending that changed contexts are one append-only token stream.
    """
    audit = validate_investigation_capture(
        bundle, expected_policy=expected_policy, allow_test_fixtures=allow_test_fixtures
    )
    tokenizer_path = Path(getattr(tokenizer, "name_or_path", ""))
    tokenizer_verified = all(
        (tokenizer_path / name).is_file()
        and hashlib.sha256((tokenizer_path / name).read_bytes()).hexdigest() == expected_policy[key]
        for name, key in [("tokenizer.json", "tokenizer_sha256"),
                          ("chat_template.jinja", "chat_template_sha256")]
    )
    _require(tokenizer_verified or audit["origin"] == "explicit_test_fixture",
             "Production decoder must load the frozen local tokenizer and chat template")
    audit["decoder_source_hashes_verified"] = tokenizer_verified
    from miles.rollout.session.samples.merge import compute_samples_from_openai_records
    from miles.rollout.session.types import SessionRecord

    for name, expected in MILES_SOURCE_HASHES.items():
        actual = hashlib.sha256(Path(sys.modules[name].__file__).read_bytes()).hexdigest()
        _require(actual == expected, f"Native Miles source differs from the reviewed pin: {name}")
    records = [SessionRecord(**deepcopy(turn["record"])) for turn in bundle["turns"]]
    args = Namespace(save_debug_trajectory_data=None, sglang_speculative_algorithm=None,
                     num_layers=45, use_rollout_routing_replay=False, use_rollout_indexer_replay=False)
    samples = compute_samples_from_openai_records(args, records, tokenizer)
    _require(len(samples) == len(records), "Native Miles dropped a generation")
    for index, (sample, turn) in enumerate(zip(samples, bundle["turns"], strict=True)):
        sample.index = index
        sample.rollout_id = bundle["rollout_id"]
        sample.group_index = bundle["group_index"]
        sample.prompt = deepcopy(turn["record"]["request"]["messages"])
        sample.metadata.update({
            "episode_id": bundle["episode_id"], "origin": audit["origin"],
            "scientific_episode_complete": True, "call_id": turn["call_id"],
            "parent_call_id": turn["parent_call_id"], "context_transition": turn["context_transition"],
            "context_event_sha256": turn.get("context_event_sha256"),
            "policy_identity": deepcopy(expected_policy), "capture_sha256": audit["capture_sha256"],
            "native_request_sha256": turn["request_sha256"],
            "native_response_sha256": turn["response_sha256"],
            "wire_request_sha256": turn["wire_request_sha256"],
            "tool_observations": deepcopy(turn.get("tool_observations", [])),
            "terminal_receipt": deepcopy(bundle["terminal"]),
            "native_miles_commit": MILES_COMMIT,
            "native_miles_source_hashes": dict(MILES_SOURCE_HASHES),
            "training_admission": "not_authorized_by_adapter; no reward or update supplied",
        })
        _require(sample.reward is None, "Adapter must not invent scientific reward")
        sample.validate()
    return samples, audit


def attach_terminal_reward(samples, *, terminal_reward, reward_receipt_sha256, reward_contract_sha256):
    """Attach an externally assessed terminal label, without claiming admission.

    The caller must independently authenticate and admit the original assessment.
    This function preserves its hashes and refuses missing labels or mixed trials;
    it does not turn a self-reported label into a verified scientific outcome.
    """
    _require(_number(terminal_reward), "Terminal reward is unavailable or non-finite")
    _require(_hash(reward_receipt_sha256) and _hash(reward_contract_sha256),
             "Terminal reward requires assessment and contract hashes")
    _require(bool(samples), "Cannot reward an empty investigation")
    first = samples[0]
    identity = (first.rollout_id, first.group_index, first.metadata.get("episode_id"),
                first.metadata.get("capture_sha256"))
    for sample in samples:
        _require((sample.rollout_id, sample.group_index, sample.metadata.get("episode_id"),
                  sample.metadata.get("capture_sha256")) == identity,
                 "Terminal reward cannot mix investigations")
        _require(sample.reward is None, "Refusing to overwrite an existing terminal label")
        _require(sample.metadata.get("scientific_episode_complete") is True,
                 "Terminal reward requires a complete investigation")
    for sample in samples:
        sample.reward = float(terminal_reward)
        sample.metadata.update({"reward_receipt_sha256": reward_receipt_sha256,
                                "reward_contract_sha256": reward_contract_sha256,
                                "training_admission": "requires separate owner source/outcome/capture admission"})
    return samples


def convert_miles_grpo_group(episodes, *, expected_group_size=4, allow_test_fixtures=False):
    """Exercise native compact-rollout GRPO conversion, without an optimizer.

    Input is one group of complete investigations, each a list of turn Samples.
    Native Miles normalizes one outcome per rollout, broadcasts that advantage
    across its turns, and divides each turn loss by the entire rollout's token
    count. Variable turn counts therefore do not create extra GRPO competitors.
    """
    _require(type(expected_group_size) is int and expected_group_size > 1,
             "GRPO needs a declared group of multiple investigations")
    _require(isinstance(episodes, list) and len(episodes) == expected_group_size,
             "Incomplete GRPO group; missing investigations cannot be dropped")
    seen_rollouts, seen_episodes, seen_calls = set(), set(), set()
    common = None
    token_counts, terminal_rewards = [], []
    flat_index = 0
    for episode in episodes:
        _require(isinstance(episode, list) and bool(episode), "Empty investigation in GRPO group")
        first = episode[0]
        meta = first.metadata
        origin = meta.get("origin")
        _require(origin == "fresh_interactive" or (allow_test_fixtures and origin == "explicit_test_fixture"),
                 "GRPO fixtures require explicit diagnostic opt-in")
        rid, eid = first.rollout_id, meta.get("episode_id")
        _require(type(rid) is int and rid not in seen_rollouts and eid and eid not in seen_episodes,
                 "Duplicate or missing investigation identity in GRPO group")
        seen_rollouts.add(rid)
        seen_episodes.add(eid)
        comparison = (first.group_index, meta.get("policy_identity"), meta.get("reward_contract_sha256"), origin)
        if common is None:
            common = comparison
        _require(comparison == common, "GRPO investigations differ in group, policy, contract or origin")
        _require(type(first.group_index) is int and _hash(meta.get("reward_contract_sha256"))
                 and _hash(meta.get("reward_receipt_sha256")), "Missing group or bound outcome contract")
        _require(_number(first.reward), "GRPO requires all terminal reward labels; none may be dropped")
        count = 0
        previous_call = None
        for sample in episode:
            sm = sample.metadata
            _require(sample.rollout_id == rid and sample.group_index == first.group_index
                     and sm.get("episode_id") == eid and sm.get("capture_sha256") == meta.get("capture_sha256")
                     and sm.get("policy_identity") == meta.get("policy_identity")
                     and sm.get("reward_contract_sha256") == meta.get("reward_contract_sha256")
                     and sm.get("reward_receipt_sha256") == meta.get("reward_receipt_sha256")
                     and sm.get("origin") == origin and sample.reward == first.reward,
                     "Mixed identity or inconsistent sibling reward")
            call = sm.get("call_id")
            _require(call and call not in seen_calls and sm.get("parent_call_id") == previous_call,
                     "Repeated or missing generation in GRPO episode")
            seen_calls.add(call)
            previous_call = call
            _require(sm.get("scientific_episode_complete") is True and not sample.remove_sample,
                     "Dropped or unfinished generation in GRPO episode")
            _require(sample.loss_mask == [1] * sample.response_length
                     and len(sample.rollout_log_probs or []) == sample.response_length,
                     "Each newly generated token must contribute exactly once")
            sample.validate()
            # Native upstream scheduling expects distinct row indices across the
            # batch; preserve the original per-episode index in the metadata.
            sm.setdefault("native_episode_sample_index", sample.index)
            sample.index = flat_index
            flat_index += 1
            count += sample.response_length
        _require(meta.get("terminal_receipt", {}).get("last_call_id") == previous_call,
                 "GRPO episode omits its committed terminal generation")
        token_counts.append(count)
        terminal_rewards.append(float(first.reward))

    from miles.ray.rollout.rollout_data_conversion import postprocess_rollout_data
    from miles.ray.rollout.train_data_conversion import convert_samples_to_train_data

    for name, expected in MILES_GROUP_SOURCE_HASHES.items():
        actual = hashlib.sha256(Path(sys.modules[name].__file__).read_bytes()).hexdigest()
        _require(actual == expected, f"Native Miles group source differs from reviewed pin: {name}")
    args = Namespace(multi_lora=False, disable_rollout_trim_samples=True,
                     use_dynamic_global_batch_size=False, global_batch_size=expected_group_size,
                     n_samples_per_prompt=expected_group_size, rollout_batch_size=1,
                     reward_key=None, advantage_estimator="grpo", rewards_normalization=True,
                     grpo_std_normalization=True, calculate_per_token_loss=False)
    flattened, metadata = postprocess_rollout_data(args, [episodes], train_parallel_config=None)
    data = convert_samples_to_train_data(args, flattened, metadata, None, None)
    _require(len(flattened) == flat_index and len(set(data["rollout_ids"])) == expected_group_size,
             "Native conversion changed the complete-investigation group")
    offset = 0
    normalized_rewards = []
    for episode, tokens in zip(episodes, token_counts, strict=True):
        rows = slice(offset, offset + len(episode))
        _require(data["rollout_mask_sums"][rows] == [tokens] * len(episode),
                 "Native loss denominator does not preserve whole-investigation credit")
        rewards = data["rewards"][rows]
        _require(all(value == rewards[0] for value in rewards), "Native sibling advantages differ")
        normalized_rewards.append(rewards[0])
        offset += len(episode)
    audit = {"schema": "ndfeb-native-miles-grpo-group-v1", "origin": common[3],
             "native_miles_commit": MILES_COMMIT, "source_hashes": MILES_GROUP_SOURCE_HASHES,
             "group_index": common[0], "investigations": expected_group_size,
             "turn_samples": flat_index, "turns_per_investigation": [len(e) for e in episodes],
             "generated_tokens_per_investigation": token_counts,
             "terminal_rewards": terminal_rewards, "normalized_rewards_per_investigation": normalized_rewards,
             "loss_mode": "one token-weighted mean per complete investigation",
             "generated_token_targets": sum(token_counts), "prompt_tool_token_targets": 0,
             "weight_updates": 0, "owner_admission_required": True}
    return data, audit


def main(argv=None):
    """Export native Samples; this command cannot run inference or weight updates."""
    import argparse

    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--capture", type=Path, required=True)
    parser.add_argument("--policy", type=Path, required=True,
                        help="Separately frozen, exact served policy_identity JSON object")
    parser.add_argument("--tokenizer", type=Path, required=True,
                        help="Local pinned tokenizer directory; network downloads disabled")
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--allow-test-fixtures", action="store_true")
    args = parser.parse_args(argv)
    _require(not args.output.exists(), "Refusing to overwrite a native assembly receipt")
    from transformers import AutoTokenizer

    capture = json.loads(args.capture.read_text())
    policy = json.loads(args.policy.read_text())
    tokenizer = AutoTokenizer.from_pretrained(args.tokenizer, local_files_only=True,
                                               trust_remote_code=False)
    samples, audit = build_miles_investigation(
        capture, tokenizer, expected_policy=policy, allow_test_fixtures=args.allow_test_fixtures
    )
    result = {"schema": "ndfeb-native-miles-assembly-v1", "audit": audit,
              "capture_file_sha256": hashlib.sha256(args.capture.read_bytes()).hexdigest(),
              "policy_file_sha256": hashlib.sha256(args.policy.read_bytes()).hexdigest(),
              "samples": [sample.to_dict() for sample in samples],
              "weight_updates": 0, "reward_supplied": False,
              "training_admission": "requires separate owner source/outcome/capture admission"}
    args.output.parent.mkdir(parents=True, exist_ok=True)
    with args.output.open("x") as file:
        json.dump(result, file, indent=2, allow_nan=False)
        file.write("\n")
    print(json.dumps({"samples": len(samples), "origin": audit["origin"], "weight_updates": 0}))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
